mapper.update:
UPDATE notification_delivery_outbox
SET status='RETRY',attempts=attempts+1,next_attempt_at=#{nextAttemptAt},last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')

UPDATE notification_delivery_outbox
SET status='FALLBACK',attempts=attempts+1,processed_at=CURRENT_TIMESTAMP,last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')

UPDATE notification_delivery_outbox
SET status='DEAD',attempts=attempts+1,processed_at=CURRENT_TIMESTAMP,last_error=#{error}
WHERE id=#{id} AND status IN ('NEW','RETRY')

mapper.select:
SELECT COUNT(*) FROM notification_delivery_outbox o
JOIN notification_projection_windows w ON w.id=#{windowId}
WHERE o.created_at>=w.started_at AND o.status IN ('NEW','RETRY','DEAD','FALLBACK')

SELECT COUNT(*) FROM (
  SELECT passed FROM notification_projection_audits
  WHERE window_id=#{windowId} ORDER BY id DESC LIMIT #{limit}
) recent WHERE passed=TRUE
